use soroban_sdk::{contract, contractimpl, Env};

#[contractimpl]
impl MyContract {
    pub fn update(env: Env, val: i128) {
        env.storage().instance().set(&"key", &val);
    }
}

use soroban_sdk::{contract, contractimpl, Env};

#[contractimpl]
impl MyContract {
    pub fn __constructor(env: Env) {
        env.storage().instance().set(&"upgraded", &true);
    }

    pub fn update(env: Env, val: i128) {
        env.storage().instance().set(&"key", &val);
    }
}
